from __future__ import absolute_import
import logging
import os
import re
import sys
from collections import namedtuple

from robot.api import logger
import taf.internal.robot_typecasts as robot_typecasts

from hran_file_operations.exceptions import ConnectionParametersError, \
    ParsingError
from hran_file_operations.remote.file_download import FileGetter

Alarm = namedtuple("fault", "id, name, source, times")


class RawAlarmHistoryParser(object):
    """
    | **Author:** damian.skrzypczak@nokia.com
    | **Maintainer:** damian.skrzypczak@nokia.com
    | **Released with version:** ---

    | **Full description:**
    | General RawAlarmHistory Parser library
    | for LTE, SBTS17 and WCDMA technologies.
    """

    def __init__(self):
        super(RawAlarmHistoryParser, self).__init__()
        self._rah_file_content = ""
        self.alarms = {"Active": [], "Inactive": []}
        self.content_deliverer = None
        self._last_downloaded_rah_file_path = None

    def rah_set_connection_parameters(self, local_path="", target_path="",
                                      target_ip="", target_username="",
                                      target_password="",
                                      via_ip="", via_username="",
                                      via_password="",
                                      destination_directory="./",
                                      via_vm=False):
        """
        Keyword for establishing connection
        for raw alarm history content delivery

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Function that set's parameters for parser's data deliverer\
        | Even if any of argument's isn't physically mandatory
        | (all of them have default values),
        | if there's no 'local_path' or 'target_ip' given,
        | ConnectionParametersError will be returned.

        **Input Parameters:**

        +-----------------------+--------+------------------------------------+
        | Input Parameters      | Man.   | Description                        |
        +=======================+========+====================================+
        | local_path            | No     | local_path to file that contains   |
        |                       |        | RawAlarmHistory content            |
        +-----------------------+--------+------------------------------------+
        | target_ip             | No     | ip of target system module         |
        |                       |        | (MSM or EXSM), that contains       |
        |                       |        | desirable file                     |
        +-----------------------+--------+------------------------------------+
        | target_username       | No     | username/login for target          |
        |                       |        | system module (MSM or EXSM),       |
        |                       |        | default set for MSM                |
        +-----------------------+--------+------------------------------------+
        | target_password       | No     | password for target                |
        |                       |        | system module (MSM or EXSM),       |
        |                       |        | default set for MSM                |
        +-----------------------+--------+------------------------------------+
        | via_ip                | No     | ip for middle-handler              |
        |                       |        | for connection and downloading     |
        +-----------------------+--------+------------------------------------+
        | via_username          | No     | username/login for middle-handler  |
        |                       |        | for connection and downloading     |
        +-----------------------+--------+------------------------------------+
        | via_password          | No     | password for middle-handler        |
        |                       |        | for connection and downloading     |
        +-----------------------+--------+------------------------------------+
        | destination_directory | No     | destination directory for where    |
        |                       |        | file will be delivered             |
        |                       |        | and from where load                |
        +-----------------------+--------+------------------------------------+
        | via_vm                | No     | flag for connection via another    |
        |                       |        | virtual machine,                   |
        |                       |        | connected to EXMS, default=False   |
        +-----------------------+--------+------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${some_logs_local_path}=  Rah set connection parameters
           ... local_path=rah.txt  target_path=/rah/file/path.txt
           ... target_ip=X.X.X.X target_username=XX  target_password=XX
           ... via_ip=Y.Y.Y.Y  via_username=YY  via_password=YY
           ... destination_directory="./rah.txt"  via_vm=True

        """
        self.content_deliverer = RawAlarmHistoryFileContentDeliverer(
            local_path, target_path, target_ip,
            target_username,
            target_password, via_ip, via_username,
            via_password, destination_directory, via_vm)

    def rah_check_alarm_by_id(self, fault_id, is_active=True,
                              search_all=False):
        """
        Keyword for checking alarm basing only on id and it's status

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | fault_id           | Yes    | id of checking alarm                  |
        |                    |        | (might be int or string)              |
        +--------------------+--------+---------------------------------------+
        | is_active          | No     | status flag of expected alarm         |
        |                    |        | (bool) (default True)                 |
        +--------------------+--------+---------------------------------------+
        | search_all         | No     | search alarm in active                |
        |                    |        | and inactive alarms                   |
        +--------------------+--------+---------------------------------------+

        **Example1:**

        .. code-block:: robotframework

           # Check if there is active alarm with id 2001
           Rah check alarm by id  2001

        **Example2:**

        .. code-block:: robotframework

           # Check if there is inactive alarm with id 2005
           Rah check alarm by id  2005  is_active=False

        | **Return value**
        | When alarm exits in chosen group:
        |   - Dictionary with alarm's occurrences in time
        |   Keys: "all",
        |         "last 10s",
        |         "last min",
        |         "last h",
        |         "last day",
        |         "current 10s",
        |         "current min",
        |         "current h",
        |         "current day"
        | Else
        |   - False (bool)
        """
        rah_content, self._last_downloaded_rah_file_path = \
            self.content_deliverer.get_rah_content()
        self.alarms = self._parse(rah_content)
        proper_alarms_group = self._get_chosen_alarms(is_active)
        if search_all:
            proper_alarms_group = list(self.alarms["Inactive"]) + list(
                self.alarms["Active"])
        found_alarms = [alarm for alarm in proper_alarms_group if
                        alarm.id == fault_id]
        return found_alarms or False

    def rah_check_alarm_by_full_data(self, fault_id, name, source,
                                     is_active=True):
        """
        Keyword for checking alarm basing on all it's data

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | fault_id           | Yes    | id of checking alarm                  |
        |                    |        | (might be int or string)              |
        +--------------------+--------+---------------------------------------+
        | name               | Yes    | name of checking alarm                |
        +--------------------+--------+---------------------------------------+
        | source             | Yes    | source of checking alarm              |
        +--------------------+--------+---------------------------------------+
        | is_active          | No     | status flag of expected alarm         |
        |                    |        | (bool) (default True)                 |
        +--------------------+--------+---------------------------------------+

        **Example1:**

        .. code-block:: robotframework

           # Check if there is active alarm with id 2001,
           # name ExtA10 and source FSM1/HWPORT4
           Rah check alarm by full data  id=2001  name=ExtA10
           ...  source=FSM1/HWPORT4

        **Example2:**

        .. code-block:: robotframework

           # Check if there is active alarm with id 2005,
           # name ExtA22 and source FSM1/HWPORT5
           Rah check alarm by full data  id=20015  name=ExtA2
           ...  source=FSM1/HWPORT5  is_active=False

        | **Return value**
        | When alarm exits in chosen group:
        |   - Dictionary with alarm's occurrences in time
        |   Keys: "all",
        |         "last 10s",
        |         "last min",
        |         "last h",
        |         "last day",
        |         "current 10s",
        |         "current min",
        |         "current h",
        |         "current day"
        | Else
        |   - False (bool)
        """
        rah_content, self._last_downloaded_rah_file_path = \
            self.content_deliverer.get_rah_content()
        self.alarms = self._parse(rah_content)
        found_alarms = self._extract_chosen_alarms(fault_id, is_active, name,
                                                   source)

        return found_alarms[0] if found_alarms else False

    def _extract_chosen_alarms(self, fault_id, is_active, name, source):
        chosen_alarms_group = self._get_chosen_alarms(is_active)
        found_alarms = []
        for alarm in chosen_alarms_group:
            if (alarm.id == fault_id
                    and alarm.name == name
                    and alarm.source == source):
                found_alarms.append(alarm)
        return found_alarms

    def _get_chosen_alarms(self, is_active):
        is_active = robot_typecasts.to_boolean(is_active)
        if is_active:
            chosen_alarms_group = self.alarms["Active"]
        else:
            chosen_alarms_group = self.alarms["Inactive"]
        return chosen_alarms_group

    def rah_get_path_of_last_parsed_file(self):
        """
        Keyword for getting path of last parsed raw_alarm_history_file

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Example:**

        .. code-block:: robotframework

           ${last_parsed_file}=  Rah get name of last parsed file

        | **Return value:**
        | path to last parsed raw_alarm_history_file
        """
        return self._last_downloaded_rah_file_path

    def _parse(self, rah_content):
        """
        Main file parsing method that splits RawAlarmHistory.txt content
        for two main tables (Active and Inactive) then
        fills self.alarms with alarms
        extracted by _parse_single_alarms_table method.
        """
        try:
            alarms_table = rah_content
            logging.debug(alarms_table)
            active_alarms_table, inactive_alarms_table = \
                self._extract_alarms_tables_from_rah(
                    alarms_table)
            return {
                "Active": self._parse_single_alarms_table(active_alarms_table),
                "Inactive": self._parse_single_alarms_table(
                    inactive_alarms_table)
            }

        except Exception as exc:
            logging.debug("Couldn't parse RawAlarmHistory.txt content",
                          exc_info=True)
            raise ParsingError(exc)

    def _extract_alarms_tables_from_rah(self, alarms_table):
        alarms_table_lines = alarms_table.splitlines()
        active_alarms_index = None
        inactive_alarms_index = None
        for index, line in enumerate(alarms_table_lines):
            found = re.match(r"\s+([A-z]+)\s[Ff]aults", line)
            if found:
                if found.groups()[0] == "Active":
                    active_alarms_index = index
                elif found.groups()[0] == "Inactive":
                    inactive_alarms_index = index
        active_alarms_table = alarms_table_lines[
                              active_alarms_index:inactive_alarms_index]
        inactive_alarms_table = alarms_table_lines[inactive_alarms_index:]
        return active_alarms_table, inactive_alarms_table

    def _parse_single_alarms_table(self, alarms_table):
        """
        For given alarms table splitting it into single alarms and returning
        parsed_alarms_table which contains single
        alarms data converted to "Alarm" nametuple objects.
        """
        start_parsing = False
        parsed_alarms_table = []
        for row in alarms_table:
            if row and start_parsing:
                fault = self._extract_fault_from_row(row)
                parsed_alarms_table.append(fault)
            elif re.match(r"[=-]{6,}", row):
                start_parsing = True
        return parsed_alarms_table

    def _extract_fault_from_row(self, row):
        parsed_line = [i.strip() for i in row.split("\t") if i]
        time_dict = self._create_times_dict(parsed_line)
        alarm_id = re.search(r"(\d+)", parsed_line[1]).group()
        fault = Alarm(id=alarm_id,
                      name=parsed_line[2],
                      source=parsed_line[3].split()[0],
                      times=time_dict)
        return fault

    @staticmethod
    def _create_times_dict(parsed_line):
        """
        For given time_dict, filling it by moving backwards on last 9 elements:
            - first getting last element from list with describing
              number of general alarm's occurrences.

            - second with step 2 starting from index
              -2 to -8 (for "last" type occurrences of alarm).

            - third also with step 2 staring from index
              -3 to -9 (for "current" type occurrences of alarm).
        """
        time_dict = {"all": int(parsed_line[-1])}
        n = 0
        for period_type in "last", "current":
            for period in "day", "h", "min", "10s":
                n += 2
                time_dict[period_type + " " + period] = int(parsed_line[-n])
            n = 1
        return time_dict

    def find_active_alarm_in_rah(self, rah_file, alarm_id):
        """
        Keyword for searching for given alarm on active alarms list

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | rah_file           | Yes    | Path to the RawAlarmHistory           |
        |                    |        | file uploaded from BTS                |
        +--------------------+--------+---------------------------------------+
        | alarm_id           | Yes    | Alarm ID                              |
        +--------------------+--------+---------------------------------------+

        | **Return value:**
        | True if alarm found else False
        """
        try:
            if any(self._find_faults(alarm_id, rah_file)):
                return True
        except IOError as e:
            logger.error("Cannot parse RAH file because of IOError. TC ended.")
            raise Exception(
                "I/O Error({errno}): {strerror}".format(errno=e.errno,
                                                        strerror=e.strerror))
        except Exception:
            logger.error("Unexpected error. TC ended.")
            raise Exception("Unexpected error: ", sys.exc_info()[0])
        return False

    def _find_faults(self, alarm_id, rah_file):
        with open(rah_file, 'r') as f:
            file_content = f.read()
            alarms = self._parse(file_content)
            active_alarms = alarms["Active"]
            found_alarms = [fault for fault in active_alarms if
                            fault.id == str(alarm_id)]
        return found_alarms

    def rah_get_all_alarms(self, is_active=True):
        """
        Keyword for getting all alarms with source as list of tuples.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | is_active          | No     | status flag of expected alarm         |
        |                    |        | (bool) (default True)                 |
        +--------------------+--------+---------------------------------------+

        **Example1:**

        .. code-block:: robotframework

           # Check if there is active alarm
           Rah check alarm by id

        **Example2:**

        .. code-block:: robotframework

           # Check if there is inactive alarm
           Rah check alarm by id  is_active=False

        | **Return value:**
        | When any alarm exits in chosen group:
        |   - returns information about id and source: [(id, source)]
        | Else:
        |   - False (bool)
        """
        rah_content, self._last_downloaded_rah_file_path = \
            self.content_deliverer.get_rah_content()
        self.alarms = self._parse(rah_content)
        proper_alarms_group = self._get_chosen_alarms(is_active)
        found_alarms = [(alarm.id, alarm.source) for alarm in
                        proper_alarms_group]
        return found_alarms


class RawAlarmHistoryFileContentDeliverer(object):
    def __init__(self, local_path="", target_path="", target_ip="",
                 target_user="",
                 target_password="", via_ip="", via_user="",
                 via_password="", destination_directory="./", via_vm=False):
        self.local_path = local_path
        if target_path:
            self.target_path = target_path
        else:
            self.target_path = "/tmp/bts/RawAlarmHistory.txt"
        self.target_ip = target_ip
        self.target_user = target_user
        self.target_password = target_password

        self.via_ip = via_ip
        self.via_user = via_user
        self.via_password = via_password

        self.destination_directory = destination_directory
        self.via_vm = via_vm

    def get_rah_content(self):
        """
        Keyword for getting raw alarm history content

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Function connects to system module
        | and get content of RawAlarmHistory.txt file.

        | **Return value**
        | - content of RawAlarmHistory.txt
        | - path to RawAlarmHistory.txt
        """
        destination_directory, destination_filename = \
            self.resolve_destination()
        source_path = self.local_path if self.local_path else self.target_path
        if self.target_ip:
            final_file_path = self.get_file_from_remote(destination_directory,
                                                        destination_filename,
                                                        source_path)
        elif self.local_path:
            final_file_path = self.get_file_from_local()
        else:
            raise ConnectionParametersError(
                "There no given parameters for getting RawAlarmHistory data")

        return open(final_file_path).read(), final_file_path

    def resolve_destination(self):
        if os.path.isdir(self.destination_directory):
            destination_directory, destination_filename = \
                self.resolve_destination_dir()
        else:
            destination_directory, destination_filename = \
                self.resolve_destination_file()
        return destination_directory, destination_filename

    def resolve_destination_file(self):
        destination_directory, destination_filename = os.path.split(
            self.destination_directory)
        destination_directory = os.path.join(destination_directory, "")
        return destination_directory, destination_filename

    def resolve_destination_dir(self):
        destination_directory = self.destination_directory
        destination_filename = ""
        return destination_directory, destination_filename

    def get_file_from_remote(self, destination_directory, destination_filename,
                             source_path):
        if self.via_ip:
            final_file_path = self.get_file_from_extension(
                destination_directory, source_path)
        else:
            final_file_path = self.get_file_from_master(destination_directory,
                                                        source_path)
        if destination_filename:
            final_file_path = self.rename_file(final_file_path,
                                               full_name=destination_filename)
        return final_file_path

    def get_file_from_local(self):
        final_file_path = self.local_path
        return final_file_path

    def get_file_from_extension(self, destination_directory, source_path):
        logging.debug("chosen extension")
        final_file_path = FileGetter.get_file_from_extension(
            source_path=source_path, destination_path=destination_directory,
            target_ip=self.target_ip, target_username=self.target_user,
            target_password=self.target_password,
            via_ip=self.via_ip, via_username=self.via_user,
            via_password=self.via_password, via_vm=self.via_vm
        )
        final_file_path = self.rename_file(final_file_path, prefix="ESM")
        return final_file_path

    def get_file_from_master(self, destination_directory, source_path):
        logging.debug("chosen master")
        final_file_path = FileGetter.get_file_from_master_sysmod(
            source_path=source_path, destination_path=destination_directory,
            ip=self.target_ip,
            username=self.target_user, password=self.target_password)
        return final_file_path

    def rename_file(self, filepath, prefix="", full_name=""):
        path, filename = os.path.split(filepath)
        if prefix:
            new_filename = prefix + "_" + filename
        elif full_name:
            new_filename = full_name
        else:
            new_filename = filename
        new_filepath = os.path.join(path, new_filename)
        os.rename(filepath, new_filepath)
        return new_filepath
